const value = String($json.postulacion ?? '').trim();
if (!value) throw new Error('BOT_TOOL_INVALID_INPUT: se requiere el id de postulacion o numero de ticket');
if (value.length > 100) throw new Error('BOT_TOOL_INVALID_INPUT: valor de postulacion demasiado largo');
return [{ json: { postulacion: value } }];
